// ---------------------------------------------------------------- queries

/// The rows of an account-level table, in `order`.
async fn account_rows<E: EntityTrait>(
    state: &AppState,
    account: E::Column,
    account_id: Uuid,
    order: impl IntoIterator<Item = E::Column>,
) -> ApiResult<Vec<E::Model>> {
    let mut select = E::find().filter(account.eq(account_id));
    for column in order {
        select = select.order_by_asc(column);
    }
    Ok(select.all(&state.db).await?)
}

/// `$account->…()->findOrFail($id)`: a row of the caller's account, else 404.
async fn account_row<E>(state: &AppState, account: E::Column, account_id: Uuid, row_id: Id) -> ApiResult<E::Model>
where
    E: EntityTrait,
    E::PrimaryKey: PrimaryKeyTrait<ValueType = Id>,
{
    E::find_by_id(row_id).filter(account.eq(account_id)).one(&state.db).await?.ok_or_else(ApiError::not_found)
}

/// The reasons of each call reason type, by id.
async fn reasons_by_type(state: &AppState, type_ids: Vec<Id>) -> ApiResult<HashMap<Id, Vec<call_reasons::Model>>> {
    let mut out: HashMap<Id, Vec<call_reasons::Model>> = HashMap::new();
    if type_ids.is_empty() {
        return Ok(out);
    }
    let rows = call_reasons::Entity::find()
        .filter(call_reasons::Column::CallReasonTypeId.is_in(type_ids))
        .order_by_asc(call_reasons::Column::Id)
        .all(&state.db)
        .await?;
    for r in rows {
        out.entry(r.call_reason_type_id).or_default().push(r);
    }
    Ok(out)
}

/// `$reasonType->callReasons()->findOrFail($id)` of a type of the account.
async fn call_reason(state: &AppState, account_id: Uuid, type_id: Id, reason_id: Id) -> ApiResult<call_reasons::Model> {
    let t = account_row::<call_reason_types::Entity>(state, call_reason_types::Column::AccountId, account_id, type_id)
        .await?;
    call_reasons::Entity::find_by_id(reason_id)
        .filter(call_reasons::Column::CallReasonTypeId.eq(t.id))
        .one(&state.db)
        .await?
        .ok_or_else(ApiError::not_found)
}

