#[derive(Debug, Default, Deserialize, IntoParams)]
#[into_params(parameter_in = Query)]
pub struct ListAccountCurrenciesQuery {
    pub active: Option<bool>,
}

#[utoipa::path(
    get,
    path = "/account/currencies",
    operation_id = "listAccountCurrencies",
    tag = "Account",
    summary = "List all currencies with their state in the account",
    params(ListAccountCurrenciesQuery),
    responses((status = 200, description = "All currencies, not paginated.", body = AccountCurrencyList), (status = 401, description = "No valid session or token (`unauthenticated`)."), (status = 403, description = "`forbidden`, `csrf_token_mismatch`, `email_not_verified`, `token_ability_missing`, `password_confirmation_required` or `signup_disabled`.")),
    extensions(("x-permission" = json!("account:member")), ("x-inventory" = json!(["R315", "R327"])), ("x-services" = json!([])))
)]
pub async fn list_account_currencies(
    State(state): State<AppState>,
    Auth(id): Auth,
    Query(query): Query<ListAccountCurrenciesQuery>,
) -> ApiResult<Json<AccountCurrencyList>> {
    let mut select =
        account_currency::Entity::find().filter(account_currency::Column::AccountId.eq(id.user.account_id));
    if let Some(active) = query.active {
        select = select.filter(account_currency::Column::Active.eq(active));
    }
    let rows = select.find_also_related(currencies::Entity).all(&state.db).await?;
    let mut data: Vec<AccountCurrency> =
        rows.into_iter().filter_map(|(row, c)| c.map(|c| AccountCurrency::new(c, row.active))).collect();
    data.sort_by(|a, b| a.code.cmp(&b.code).then(a.id.cmp(&b.id)));
    Ok(Json(AccountCurrencyList { data }))
}

